def _decode_plan_range_side(value):
    """Validate one base/target range side of a replay operation.

    Returns ``None`` for a null side, otherwise the normalized
    ``[versions, gaps, receipt, ready]`` list with versions/gaps as
    lists and the receipt as the five-field normalized list.
