    previous = None
    seen_versions = set()
    for raw_record in raw_versions:
        if not isinstance(raw_record, list) or len(raw_record) != 4:
            raise ValueError("each range version must be an array of four values")
        batch, record_previous, version, passed = raw_record
        if isinstance(batch, bool) or not isinstance(batch, int):
            raise ValueError("range batch must be a non-bool integer")
        if versions and batch <= versions[-1][0]:
            raise ValueError("range versions must be sorted uniquely by batch")
        if record_previous != previous:
            raise ValueError("range previous must be the version of the preceding "
                             "batch (null for the first)")
        if not isinstance(version, str):
            raise ValueError("range version must be a str")
        if not version or not set(version) <= _DELIVERY_IDENT_CHARS:
            raise ValueError(
                "range version must be non-empty and contain only ASCII "
                "alphanumeric characters and ._-"
            )
        if version in seen_versions:
            raise ValueError(f"range version {version!r} is reused")
        if not isinstance(passed, bool):
            raise ValueError("range passed flag must be a boolean")
        versions.append([batch, record_previous, version, passed])
        seen_versions.add(version)
        previous = version

    if not isinstance(raw_gaps, list):
        raise ValueError("range gaps must be an array")
    gaps = []
    for raw_gap in raw_gaps:
        if not isinstance(raw_gap, list) or len(raw_gap) != 2:
            raise ValueError("each range gap must be an array of two values")
        first, last = raw_gap
        if isinstance(first, bool) or not isinstance(first, int):
            raise ValueError("range gap first must be a non-bool integer")
        if isinstance(last, bool) or not isinstance(last, int):
            raise ValueError("range gap last must be a non-bool integer")
        if first > last:
            raise ValueError("range gap first must not exceed last")
        gaps.append([first, last])

    receipt = (None if raw_receipt is None
               else _decode_update_receipt(raw_receipt))
    if not isinstance(ready, bool):
        raise ValueError("range ready must be a boolean")
    return [versions, gaps, receipt, ready]


