                (kind == "remove") == (len(action) == 2)):
            record = _decode_update_record(
                action[1] if kind == "remove" else action[1],
                batch_min, batch_max)
            batch = record[0]
            existing = present.get(batch)
            if existing is None:
                raise ValueError(f"a {kind} action requires batch {batch!r} "
                                 "to be present in the base")
            if existing != record:
                raise ValueError(f"the {kind} action record must match the "
                                 "base record at batch {batch!r}")
            if kind == "remove":
                del present[batch]
            else:
                replacement = _decode_update_record(action[2], batch_min,
                                               batch_max)
                if replacement[0] != batch:
                    raise ValueError("a replace action must keep the same "
                                     "batch")
                present[batch] = replacement
